const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const taklamakan = ee.Geometry.Rectangle([75, 37, 90, 42]); // Approximate Taklamakan Desert bounds

  // 2. Data Acquisition
  const feb2019 = ee.ImageCollection('MODIS/061/MOD04_L2')
    .filterDate('2019-02-01', '2019-03-01')
    .filterBounds(taklamakan);

  const feb2020 = ee.ImageCollection('MODIS/061/MOD04_L2')
    .filterDate('2020-02-01', '2020-03-01')
    .filterBounds(taklamakan);

  // Check collection sizes
  const count2019 = feb2019.size().getInfo();
  const count2020 = feb2020.size().getInfo();

  console.log(`2019 Images: ${count2019}, 2020 Images: ${count2020}`);

  if (count2019 === 0 || count2020 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean AOD composites
  const aod2019 = feb2019.select('Aerosol_Optical_Depth_Land_Ocean').mean();
  const aod2020 = feb2020.select('Aerosol_Optical_Depth_Land_Ocean').mean();

  // Check valid pixels
  const count2019Pixels = aod2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: taklamakan,
    scale: 1000,
    maxPixels: 1e9
  }).get('Aerosol_Optical_Depth_Land_Ocean').getInfo();

  const count2020Pixels = aod2020.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: taklamakan,
    scale: 1000,
    maxPixels: 1e9
  }).get('Aerosol_Optical_Depth_Land_Ocean').getInfo();

  console.log(`2019 Valid Pixels: ${count2019Pixels}, 2020 Valid Pixels: ${count2020Pixels}`);

  if (count2019Pixels === 0 || count2020Pixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean AOD values
  const meanAOD2019 = aod2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: taklamakan,
    scale: 1000,
    maxPixels: 1e9
  }).get('Aerosol_Optical_Depth_Land_Ocean').getInfo();

  const meanAOD2020 = aod2020.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: taklamakan,
    scale: 1000,
    maxPixels: 1e9
  }).get('Aerosol_Optical_Depth_Land_Ocean').getInfo();

  console.log(`Mean AOD 2019: ${meanAOD2019?.toFixed(3)}, 2020: ${meanAOD2020?.toFixed(3)}`);

  // 5. Validation & Final Answer
  if (meanAOD2019 === null || meanAOD2020 === null || 
      isNaN(meanAOD2019) || isNaN(meanAOD2020) ||
      meanAOD2019 < 0 || meanAOD2019 > 3 || 
      meanAOD2020 < 0 || meanAOD2020 > 3) {
    console.log("<answer>C3</answer>");
  } else if (meanAOD2020 > meanAOD2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
